CREATE TABLE IF NOT EXISTS "purchase_returns" (
  "return_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "farm_id" bigint NOT NULL,
  "purchase_id" bigint NOT NULL,
  "return_number" text NOT NULL,
  "return_date" text NOT NULL,
  "quantity" double precision NOT NULL,
  "return_amount" double precision NOT NULL,
  "refund_method" text DEFAULT 'cash',
  "reason" text,
  "created_at" text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("return_id")
);

CREATE TABLE IF NOT EXISTS "receive_vouchers" (
  "voucher_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "farm_id" bigint NOT NULL,
  "customer_id" bigint NOT NULL,
  "voucher_number" text,
  "date" text NOT NULL,
  "amount" double precision DEFAULT 0 NOT NULL,
  "payment_source" text DEFAULT 'cash',
  "bank_id" bigint,
  "reference" text,
  "notes" text,
  "created_at" text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("voucher_id")
);

CREATE TABLE IF NOT EXISTS "sales" (
  "sale_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "flock_id" bigint NOT NULL,
  "date" text NOT NULL,
  "vehicle_number" text,
  "broker" text,
  "empty_weight" double precision,
  "load_weight" double precision,
  "bird_weight" double precision,
  "rate" double precision NOT NULL,
  "total_amount" double precision NOT NULL,
  "payment_type" text DEFAULT 'cash',
  "driver_name" text DEFAULT '',
  "driver_phone" text DEFAULT '',
  "receipt_image" text,
  "module_type" text DEFAULT 'broiler',
  "payment_source" text DEFAULT 'cash',
  "bank_id" bigint,
  PRIMARY KEY ("sale_id")
);

CREATE TABLE IF NOT EXISTS "sales_orders" (
  "order_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "farm_id" bigint NOT NULL,
  "customer_id" bigint,
  "product_id" bigint NOT NULL,
  "date" text NOT NULL,
  "quantity" double precision NOT NULL,
  "selling_price" double precision NOT NULL,
  "total_amount" double precision NOT NULL,
  "payment_type" text DEFAULT 'cash',
  "amount_paid" double precision DEFAULT 0,
  "notes" text,
  PRIMARY KEY ("order_id")
);

CREATE TABLE IF NOT EXISTS "sales_return_items" (
  "item_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "return_id" bigint NOT NULL,
  "bill_id" bigint NOT NULL,
  "bill_item_id" bigint,
  "product_id" bigint,
  "product_name" text NOT NULL,
  "quantity" double precision NOT NULL,
  "unit_price" double precision NOT NULL,
  "total_price" double precision NOT NULL,
  PRIMARY KEY ("item_id")
);

CREATE TABLE IF NOT EXISTS "sales_returns" (
  "return_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "farm_id" bigint NOT NULL,
  "bill_id" bigint NOT NULL,
  "return_number" text NOT NULL,
  "return_date" text NOT NULL,
  "return_amount" double precision NOT NULL,
  "refund_amount" double precision DEFAULT 0,
  "refund_method" text DEFAULT 'cash',
  "reason" text,
  "created_at" text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("return_id")
);

CREATE TABLE IF NOT EXISTS "supplier_ledger" (
  "ledger_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "supplier_id" bigint NOT NULL,
  "transaction_date" text NOT NULL,
  "description" text,
  "debit" double precision DEFAULT 0,
  "credit" double precision DEFAULT 0,
  "balance" double precision DEFAULT 0,
  "reference_type" text,
  "reference_id" bigint,
  "created_at" text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "voucher_id" bigint,
  "notes" text,
  PRIMARY KEY ("ledger_id")
);

CREATE TABLE IF NOT EXISTS "suppliers" (
  "supplier_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "farm_id" bigint NOT NULL,
  "supplier_name" text NOT NULL,
  "phone" text,
  "products_supplied" text,
  PRIMARY KEY ("supplier_id")
);

CREATE TABLE IF NOT EXISTS "vaccinations" (
  "vaccination_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "batch_id" bigint,
  "flock_id" bigint,
  "date" text NOT NULL,
  "vaccine_name" text NOT NULL,
  "dose" text,
  "notes" text,
  "cost" double precision DEFAULT 0,
  "done" bigint DEFAULT 0,
  "bill_id" bigint,
  "bill_number" text,
  PRIMARY KEY ("vaccination_id")
);
